export type Dict = Record<string, string>;

function pack(rows: Record<string, [string, string, string, string, string]>): {
  tr: Dict;
  en: Dict;
  de: Dict;
  ar: Dict;
  ru: Dict;
} {
  const tr: Dict = {};
  const en: Dict = {};
  const de: Dict = {};
  const ar: Dict = {};
  const ru: Dict = {};
  for (const [k, v] of Object.entries(rows)) {
    tr[k] = v[0];
    en[k] = v[1];
    de[k] = v[2];
    ar[k] = v[3];
    ru[k] = v[4];
  }
  return { tr, en, de, ar, ru };
}

