  "notif.p3d": ["Seçtiğiniz veya tarayıcı konumunuza 80 km içindeki yeni ilanlar.", "New ads within 80 km of your selected or GPS location.", "Neue Anzeigen im Umkreis von 80 km.", "إعلانات جديدة ضمن 80 كم من موقعك.", "Новые объявления в радиусе 80 км."],
  "notif.geo.on": ["Aktif konum: {city}", "Active location: {city}", "Aktiver Standort: {city}", "الموقع النشط: {city}", "Активная локация: {city}"],
  "notif.geo.denied": ["Tarayıcı konumunu reddettiniz. İsterseniz ili elle seçebilirsiniz.", "Location was denied. You can pick a city manually.", "Standort abgelehnt. Stadt manuell wählen.", "رُفض الموقع. يمكنك اختيار مدينة.", "Геолокация отклонена. Выберите город."],
